import type {IncomingMessage, ListSessionsMessage} from '../../types/messages.js';

const MAX_CONTENT_LENGTH = 10000;

interface ValidationSuccess {
  valid: true;
  data: IncomingMessage;
}

interface ValidationFailure {
  valid: false;
  error: string;
}

export type ValidationResult = ValidationSuccess | ValidationFailure;

const VALIDATORS: Record<string, (message: Record<string, unknown>) => ValidationResult> = {
  user_message: message => validateUserMessage(message),
  ping: message => validatePingMessage(message),
  list_sessions: message => validateListSessionsMessage(message),
};

export function validateMessage(payload: unknown): ValidationResult {
  if (typeof payload !== 'object' || payload === null) {
    return {valid: false, error: 'Message must be an object'};
  }

  const message = payload as Record<string, unknown>;

  if (typeof message.type !== 'string') {
    return {valid: false, error: 'Message must have a type field'};
  }

  const validator = Object.hasOwn(VALIDATORS, message.type) ? VALIDATORS[message.type] : undefined;
  return validator ? validator(message) : {valid: false, error: `Unknown message type: ${message.type}`};
}

function validateUserMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.content !== 'string') {
    return {valid: false, error: 'user_message must have content string'};
  }

  const trimmed = message.content.trim();

  if (trimmed.length === 0) {
    return {valid: false, error: 'Message content cannot be empty'};
  }

  if (message.content.length > MAX_CONTENT_LENGTH) {
    return {valid: false, error: `Message content too long (max ${MAX_CONTENT_LENGTH} chars)`};
  }

  return {
    valid: true,
    data: {
      type: 'user_message',
      content: message.content,
    },
  };
}

function validatePingMessage(message: Record<string, unknown>): ValidationResult {
  if (typeof message.timestamp !== 'number') {
    return {valid: false, error: 'ping must have timestamp number'};
  }

  return {
    valid: true,
    data: {
      type: 'ping',
      timestamp: message.timestamp,
    },
  };
}

const MAX_CURSOR_ID_LENGTH = 128;

function validateCursor(before: unknown): {cursor: NonNullable<ListSessionsMessage['before']>} | {error: string} {
  if (typeof before !== 'object' || before === null) {
    return {error: 'list_sessions before must be an object'};
  }
  const {updatedAt, sessionId} = before as Record<string, unknown>;
  if (typeof sessionId !== 'string' || sessionId.length < 1 || sessionId.length > MAX_CURSOR_ID_LENGTH) {
    return {error: `list_sessions before.sessionId must be 1-${MAX_CURSOR_ID_LENGTH} characters`};
  }
  const isDateLike = typeof updatedAt === 'string' || typeof updatedAt === 'number';
  if (!isDateLike || !Number.isFinite(new Date(updatedAt).getTime())) {
    return {error: 'list_sessions before.updatedAt must be a valid date'};
  }
  return {cursor: {updatedAt, sessionId}};
}

function validateListSessionsMessage(message: Record<string, unknown>): ValidationResult {
  const {limit} = message;
  if (limit !== undefined && (typeof limit !== 'number' || !Number.isInteger(limit) || limit < 0)) {
    return {valid: false, error: 'list_sessions limit must be a non-negative integer'};
  }

  const listing: ListSessionsMessage = {type: 'list_sessions'};
  if (limit !== undefined) listing.limit = limit;
  if (message.before === undefined) return {valid: true, data: listing};

  const checked = validateCursor(message.before);
  if ('error' in checked) return {valid: false, error: checked.error};
  listing.before = checked.cursor;
  return {valid: true, data: listing};
}
}

/** The one session a store holds, for asserting what survived a close. */
export async function onlySession(store: SessionStore, sessionId: string): Promise<ChatSession | undefined> {
  return (await store.get(sessionId)) as ChatSession | undefined;
}

/** Polls a condition for up to half a second, so a teardown waits for a socket to be seen closed. */
export const eventually = async (check: () => boolean): Promise<void> => {
  for (let attempt = 0; attempt < 50 && !check(); attempt++) await new Promise(resolve => setTimeout(resolve, 10));
};

/** Closes a suite's own clients, then each server once it has seen its sockets close, so no close is logged late. */
export async function closeEngines(
  hals: Array<{wss: {clients: {size: number}}; stop: () => Promise<void>}>,
  sockets: WebSocket[]
): Promise<void> {
  for (const client of sockets.splice(0)) client.terminate();
  for (const hal of hals.splice(0)) {
    await eventually(() => hal.wss.clients.size === 0);
    await hal.stop();
  }
}

/** A store with only the required members, so an optional one can be added, replaced or left out per test. */
export const delegatingTo = (inner: InMemorySessionStore): SessionStore => ({
  create: (sessionId, userId, options) => inner.create(sessionId, userId, options),
  get: sessionId => inner.get(sessionId),
  delete: sessionId => inner.delete(sessionId),
  count: () => inner.count(),
  clear: () => inner.clear(),
});
